insert into public.emergency_countries (country_code, name_en, wave, sds_rule_kind, sds_rule_summary, sds_rule_source_url, sds_rule_checked_on, state) values
  ('US', 'United States', 1, 'transport_papers_rule', 'Shipping papers for hazardous materials (49 CFR 172.604): the number must be monitored the whole time the material is in transport; the person answering must know the material or have immediate access to someone who does; call-back services such as answering machines or pagers do not meet the requirement; if an emergency response information provider is used, the papers show the registrant''s name or contract number. This is the transport rule, not the HazCom rule for the safety data sheet.', 'https://www.ecfr.gov/current/title-49/subtitle-B/chapter-I/subchapter-C/part-172/subpart-G/section-172.604', '2026-10-15', 'draft'),
  ('DE', 'Germany', 1, 'own_number_required', 'BAuA REACH-CLP-Biozid Helpdesk: the supplier states its own emergency number in section 1.4, with qualified medical advice in German. The BfR number and the general numbers 112 and 116117 are not sufficient. The number of one of the seven poison centres is offered as a paid service under a contract; a contract with any third party on the same terms works too. The BAuA page still names Regulation 2015/830 as the current Annex II, which Regulation 2020/878 replaced, so it may not have been updated.', 'https://www.reach-clp-biozid-helpdesk.de/DE/REACH/Sicherheitsdatenblatt/Sicherheitsdatenblatt-EN/Emergency-Telephone-number.html', '2026-10-15', 'draft'),
  ('NL', 'Netherlands', 1, 'national_number_listed', 'NVIC (UMC Utrecht) is the Dutch body appointed under Article 45 CLP. Its page says the number is stated in the safety data sheet, is for professional responders and medical personnel only, and needs the note "Only for the purpose of informing medical personnel in case of acute intoxications" next to it. It must not be used on labels.', 'https://nvic.umcutrecht.nl/nl/productinformatie', '2026-10-15', 'draft'),
  ('ES', 'Spain', 1, 'national_number_listed', 'INTCF is the Spanish body appointed under Article 45 CLP. MITECO (February 2022): for a limited notification the full composition of the mixture must be available through a Spanish-language telephone line, 24 hours a day, and an e-mail address for the INTCF on-call doctors.', 'https://www.miteco.gob.es/content/dam/miteco/es/calidad-y-evaluacion-ambiental/temas/productos-quimicos/notificacionesalintcf_feb22_v1_es_tcm30-536066.pdf', '2026-10-15', 'draft'),
  ('FR', 'France', 1, 'national_number_listed', 'The INERIS REACH helpdesk page gives the ORFILA number for section 1.4 of French safety data sheets. Since 12 October 2023 CAPTV runs it: the call is routed to the nearest poison centre, 24 hours a day, 7 days a week.', 'https://reach-info.ineris.fr/numero-orfila', '2026-10-15', 'draft'),
  ('IT', 'Italy', 1, 'national_number_listed', 'The register of the Istituto Superiore di Sanità lists ten poison centres (CAV) with their numbers. The page carries the version mark v. 13/02/2017. It does not say which of the centres may be named in section 1.4 of a safety data sheet.', 'https://preparatipericolosi.iss.it/cav.aspx', '2026-10-15', 'draft');
insert into public.emergency_services (country_code, slug, kind, name, operator, phone_display, phone_tel, hours_kind, hours_note, audience, languages, sds_use, sds_use_note, cost_note, source_url, source_date, verification, checked_on, state, sort) values
  ('US', 'poison-help', 'poison_centre', 'Poison Help', 'HRSA (U.S. Health Resources and Services Administration)', '1-800-222-1222', '+18002221222', '24_7', null, 'public', '{}', 'public_line', 'A public line that connects the caller to the local poison centre. The page says nothing about use in a safety data sheet or on shipping papers.', 'Free and confidential. Interpretation in 161 languages according to the text of the page (a caption on the same page says over 100).', 'https://poisonhelp.hrsa.gov/about-us', '2025-01-08', 'confirmed', '2026-10-15', 'draft', 0),
  ('US', 'national-response-center', 'spill_reporting', 'National Response Center', 'U.S. Coast Guard', '800-424-8802', '+18004248802', '24_7', null, 'not_stated', '{}', 'reporting_not_advice', 'Takes reports of oil, chemical, radiological and biological releases into the environment and of rail incidents. The source describes no product or medical advice. EPA also prints a second number, 1-202-267-2675, on its oil-discharge page.', null, 'https://epa.gov/emergency-response/national-response-center', null, 'confirmed', '2026-10-15', 'draft', 1),
  ('DE', 'berlin', 'poison_centre', 'Poison centre Berlin (Giftnotruf der Charité)', null, '030 1924 0', '+493019240', 'not_stated', null, 'not_stated', '{}', 'by_contract_only', null, null, 'https://www.bfr.bund.de/cm/343/verzeichnis-der-giftinformationszentren.pdf', '2026-07-22', 'confirmed', '2026-10-15', 'draft', 0),
