  ('NL', 'nvic', 'poison_centre', 'NVIC (Nationaal Vergiftigingen Informatie Centrum)', 'UMC Utrecht', '088 755 8000', '+31887558000', 'not_stated', null, 'professionals_only', '{}', 'national_body_for_sds', 'The page asks for the note "Only for the purpose of informing medical personnel in case of acute intoxications" next to the number. The number must not be used on labels.', null, 'https://nvic.umcutrecht.nl/nl/productinformatie', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('ES', 'sit-intcf', 'poison_centre', 'Servicio de Información Toxicológica (SIT)', 'Instituto Nacional de Toxicología y Ciencias Forenses (INTCF)', '+34 91 562 04 20', '+34915620420', '24_7', null, 'public_and_professionals', '{es}', 'national_body_for_sds', 'Listed as the national emergency telephone number of the Spanish poison centre in the ECHA table of 3 January 2024; the same number and round-the-clock service appear in the SIT annual report for 2020.', null, 'https://www.mjusticia.gob.es/es/ElMinisterio/OrganismosMinisterio/Documents/Memoria%20SIT%202020.pdf', '2020', 'dated_source', '2026-10-15', 'draft', 0),
  ('FR', 'orfila', 'national_helpdesk', 'ORFILA number (CAPTV)', 'CAPTV (Centre AntiPoison et de ToxicoVigilance), since 12 October 2023', '+33 (0)1 45 42 59 59', '+33145425959', '24_7', null, 'not_stated', '{}', 'national_body_for_sds', 'Given on the INERIS REACH helpdesk page as the number for section 1.4 of French safety data sheets. The call is routed to the nearest poison centre.', 'Free medical advice; the cost of the call is not included.', 'https://reach-info.ineris.fr/numero-orfila', null, 'confirmed', '2026-10-15', 'draft', 0),
